#!/usr/bin/env bash
case "${VERIFY_DIRECTIVE_DEPTH_OFF:-}" in ""|0|false|no|off) ;; *) exit 0 ;; esac
. "${CLAUDE_PLUGIN_ROOT_CORE:-$(cd "$(dirname "${BASH_SOURCE[0]}")/../../core" && pwd -P)}/hooks/lib/role-directive.sh"
YOU_DECIDE=$'YOU DECIDE: whether a defect exists in what was built, found by independently attempting to reproduce it — never a re-litigation of review\'s per-requirement verdict, never a holistic quality judgment, and never a fix. You prevent a defect that review\'s pass and qa\'s attempts both missed from reaching landing unchallenged.'
USE_WHEN=$'USE WHEN (phase 1, scout protocol):\nSTEPS:\n1. Read coding\'s record, qa\'s record, and review\'s record.\n2. Enumerate candidate attempts, each naming its source verbatim: a qa defect report, a review requirement marked Present, or a self-devised path.\n3. Name code_under_review: and state which closed_checks entries will be cited (cite-and-skip) versus re-derived.\nCRITERION: an attempt list where any item has no named source is rejected as too vague to act on.\nNEVER: propose a fix; re-litigate review\'s per-requirement verdict as if it were the attempt itself.'
PRODUCES=$'PRODUCES (phase 1): promise the attempt list — each attempt names, verbatim, the claim it tests (a qa defect report, a review requirement marked Present, or a path you devised), plus the code_under_review: sha and which closed_checks you will cite versus re-derive.'
HAND_OFF=$'HAND-OFF (phase 2, quality bar):\nSTEPS:\n1. Make the attempt.\n2. Record its outcome — always one of exactly three values: reproduced, not-reproduced, blocked: needs-repro-access.\n3. On reproduced, write the accompanying finding block, addressed_to: coding, with an evidence pointer (repro steps, commit sha, run output, log excerpt — never a paraphrase); reproduced with no evidence pointer is refused before write.\n4. Assign severity strictly by the deterministic band lookup (Critical/High -> blocking, Medium/Low/Unknown -> advisory), never freehand. A blocking finding is never downgraded or dropped because review\'s record is clean.\n5. Before writing cleared, check eligibility — no unresolved blocking finding, or the human\'s explicit waiver; silence is not a waiver.\nCRITERION: every attempt taken up has a recorded outcome, no exceptions, including attempts that came up empty — an unrecorded attempt is indistinguishable from one never made.\nNEVER: skip an attempt\'s outcome; merge the three-value outcome set into a pass/fail signal; set a priority/fix-urgency ranking (severity only — that call belongs to coding or a human once the finding lands); cite a closed_checks entry against a stale/non-matching code_under_review: sha (different sha: re-derive, never cite).'
core_role_directive "$YOU_DECIDE" "$USE_WHEN" "$PRODUCES" "$HAND_OFF"
